DO $$ DECLARE f record; d text; BEGIN FOR f IN SELECT oid FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname IN ('approve_payroll_run','approve_department_payroll') LOOP d:=pg_get_functiondef(f.oid); d:=replace(d,'g:=g+(row->>''gross_pay'')::numeric;', 'IF coalesce((row->>''loan_deductions'')::numeric,0)<0 OR (row->>''total_deductions'')::numeric+0.01 < (row->>''employee_nic'')::numeric+(row->>''paye'')::numeric+coalesce((row->>''loan_deductions'')::numeric,0) THEN RAISE EXCEPTION ''Loan repayment must be withheld from net pay''; END IF; g:=g+(row->>''gross_pay'')::numeric;'); EXECUTE d; END LOOP; END $$;